const { withGradleProperties } = require('@expo/config-plugins');

/**
 * Raises the AsyncStorage database ceiling.
 *
 * The Android default is 6 MB. This app writes roughly 1.2 MB of history a
 * year, so the default runs out in about five years and then silently stops
 * saving. android/ is regenerated by prebuild, so the value has to be injected
 * here rather than edited by hand.
 */
module.exports = function withAsyncStorageSize(config, { sizeInMB = 50 } = {}) {
  return withGradleProperties(config, (cfg) => {
    const key = 'AsyncStorage_db_size_in_MB';
    cfg.modResults = cfg.modResults.filter(
      (item) => !(item.type === 'property' && item.key === key),
    );
    cfg.modResults.push({ type: 'property', key, value: String(sizeInMB) });
    return cfg;
  });
};
